-- Esquema MÍNIMO das tabelas da Fase 3 (comunidade) para testes locais. Rodar após schema_academico.sql.
CREATE TABLE AVISO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, TIPO VARCHAR(50), URL VARCHAR(1000),
  TITULO VARCHAR(200), DESCRICAO TEXT, DATA_CADASTRO DATETIME);
CREATE TABLE FORUM (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, USUARIO_ID BIGINT NOT NULL,
  LISTA_DISCIPLINA_ID BIGINT NOT NULL, TITULO VARCHAR(200), DESCRICAO TEXT, VISUALIZACOES BIGINT, POSTAGENS BIGINT,
  DATA_CADASTRO DATETIME, EDITADO TINYINT(1) NOT NULL DEFAULT 0, DATA_EDICAO DATETIME);
CREATE TABLE FORUM_DISCURSAO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, USUARIO_ID BIGINT NULL,
  FORUM_ID BIGINT NULL, DISCURSAO TEXT, DATA_CADASTRO DATETIME, EDITADO TINYINT(1) NOT NULL DEFAULT 0, DATA_EDICAO DATETIME);
CREATE TABLE CHAT_MENSAGENS (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, USUARIO_SEND_ID BIGINT NOT NULL,
  USUARIO_RECEIVE_ID BIGINT NOT NULL, MENSAGEM TEXT, DATA_CADASTRO DATETIME);
CREATE TABLE VIDEO_ANOTACAO (ID BIGINT AUTO_INCREMENT PRIMARY KEY, INSTITUICAO_ID BIGINT NOT NULL, DISCIPLINA_ID BIGINT NOT NULL,
  VIDEO VARCHAR(200), POSICAO VARCHAR(20), DESCRICAO TEXT, DATA_CADASTRO DATETIME);
CREATE TABLE LISTA_SITUACAO_CR (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
CREATE TABLE LISTA_CATEGORIA_CR (ID BIGINT PRIMARY KEY, VALOR VARCHAR(50));
ALTER TABLE CONTAS_RECEBER ADD LISTA_CATEGORIA_CR_ID BIGINT NULL, ADD NUM_DOCUMENTO VARCHAR(50) NULL, ADD OBSERVACAO TEXT NULL;

INSERT INTO LISTA_SITUACAO_CR VALUES (1,'EM ABERTO'),(2,'PAGO');
INSERT INTO LISTA_CATEGORIA_CR VALUES (1,'MENSALIDADE'),(2,'MATRÍCULA');
UPDATE CONTAS_RECEBER SET LISTA_CATEGORIA_CR_ID = 1;
